import { writeFileSync } from 'node:fs';
import { centerColumnBits, naiveCenterColumn, A051023_PREFIX } from './rule30.mjs';

const N = 200_000;
const OUT = new URL('./talus7_center.bin', import.meta.url);

/** Centre column to depth n, word-packed low-end row map. */
export function centerPacked(n) {
  const WORDS = (n >> 5) + 3;
  const r = new Uint32Array(WORDS);
  r[0] = 1; // rowNat 0 = 1
  const out = new Uint8Array(n);
  for (let t = 0; t < n; t++) {
    out[t] = (r[t >> 5] >>> (t & 31)) & 1;
    // One step, words 0 .. limit. A word may only be brought into the window
    // while it is still genuinely zero -- row t occupies bits 0 .. 2t, so word
    // j is all zero until t = 16j, and (t>>4)+1 first reaches j at t = 16j-16.
    const limit = Math.min(WORDS - 1, (t >> 4) + 1);
    let prev = 0;
    for (let j = 0; j <= limit; j++) {
      const cur = r[j];
      const s2 = ((cur << 2) | (prev >>> 30)) >>> 0;
      const s1 = ((cur << 1) | (prev >>> 31)) >>> 0;
      r[j] = (s2 ^ (s1 | cur)) >>> 0;
      prev = cur;
    }
  }
  return out;
}

function check() {
  const D = 4000;
  const mine = centerPacked(D);
  const big = centerColumnBits(D);
  let bad = 0;
  for (let i = 0; i < D; i++) if (mine[i] !== big[i]) bad++;
